import{_ as e,c as a,aU as s,a as n}from"./chunks/framework.DIXiA2XH.js";const o="/assets/win001.CH10eMle.png",m=JSON.parse('{"title":"系统amd和arm的区别","description":"","frontmatter":{},"headers":[],"relativePath":"note/stationmaster/tool/系统amd和arm的区别.md","filePath":"note/stationmaster/tool/系统amd和arm的区别.md","lastUpdated":1785559210000}'),r={name:"note/stationmaster/tool/系统amd和arm的区别.md"};function l(i,t,d,g,c,h){return n(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="系统amd和arm的区别" tabindex="-1">系统amd和arm的区别 <a class="header-anchor" href="#系统amd和arm的区别" aria-label="Permalink to &quot;系统amd和arm的区别&quot;">​</a></h1><p>AMD64和ARM64是两种主流的计算机CPU架构，主要区别在于指令集、功耗特性、性能侧重和应用领域，导致它们适合完全不同的设备类型。</p><p>下面的表格快速总结了两者的核心差异：</p><table tabindex="0"><thead><tr><th style="text-align:left;">特性维度</th><th style="text-align:left;"><strong>AMD64 (x86_64)</strong></th><th style="text-align:left;"><strong>ARM64 (AArch64)</strong></th></tr></thead><tbody><tr><td style="text-align:left;"><strong>指令集</strong></td><td style="text-align:left;">复杂指令集 (CISC)</td><td style="text-align:left;">精简指令集 (RISC)</td></tr><tr><td style="text-align:left;"><strong>核心特点</strong></td><td style="text-align:left;">高性能，强通用计算能力</td><td style="text-align:left;">高能效比，低功耗</td></tr><tr><td style="text-align:left;"><strong>设计/授权</strong></td><td style="text-align:left;">由<strong>AMD/Intel</strong>设计、制造、销售</td><td style="text-align:left;">由<strong>ARM公司</strong>设计架构，授权给苹果、高通等厂商制造芯片</td></tr><tr><td style="text-align:left;"><strong>应用领域</strong></td><td style="text-align:left;">主流<strong>台式机、笔记本、服务器</strong></td><td style="text-align:left;"><strong>智能手机、平板</strong>、苹果M系列Mac、嵌入式设备（树莓派）</td></tr><tr><td style="text-align:left;"><strong>软件生态</strong></td><td style="text-align:left;">非常成熟，兼容性好</td><td style="text-align:left;">移动端生态成熟；PC端（尤其Windows）生态正在发展中</td></tr><tr><td style="text-align:left;"><strong>简化理解</strong></td><td style="text-align:left;">“为高性能桌面计算而生”</td><td style="text-align:left;">“为能效和移动设备优化”</td></tr></tbody></table><blockquote><p><strong>提示</strong>：你可能还会看到 <strong>x86_64</strong> 这个术语，它在Linux/macOS等系统中与AMD64意思相同。而 <strong>AArch64</strong> 是ARM64的官方名称，两者也完全等同。</p></blockquote><h3 id="🔍-如何快速查看你电脑的架构" tabindex="-1">🔍 如何快速查看你电脑的架构 <a class="header-anchor" href="#🔍-如何快速查看你电脑的架构" aria-label="Permalink to &quot;🔍 如何快速查看你电脑的架构&quot;">​</a></h3><p>想知道自己的电脑属于哪种架构很简单，下面是不同系统下的通用方法：</p><h4 id="💻-windows-系统" tabindex="-1">💻 <strong>Windows 系统</strong> <a class="header-anchor" href="#💻-windows-系统" aria-label="Permalink to &quot;💻 **Windows 系统**&quot;">​</a></h4><ol><li>按下 <strong><code>Win + R</code></strong> 键，输入 <code>cmd</code> 并回车，打开命令提示符。</li><li>在黑色窗口中输入 <strong><code>echo %PROCESSOR_ARCHITECTURE%</code></strong> 并回车。</li><li>查看结果：显示 <strong><code>AMD64</code></strong> 代表AMD64架构；显示 <strong><code>ARM64</code></strong> 则代表ARM64架构。</li></ol><h4 id="🐧-linux-ubuntu-系统" tabindex="-1">🐧 <strong>Linux / Ubuntu 系统</strong> <a class="header-anchor" href="#🐧-linux-ubuntu-系统" aria-label="Permalink to &quot;🐧 **Linux / Ubuntu 系统**&quot;">​</a></h4><p>打开终端（Terminal），输入以下命令并回车：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uname</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>查看结果：显示 <strong><code>x86_64</code></strong> 或 <strong><code>amd64</code></strong> 代表AMD64架构；显示 <strong><code>aarch64</code></strong> 或 <strong><code>arm64</code></strong> 则代表ARM64架构。</p><h4 id="🍎-macos-系统" tabindex="-1">🍎 <strong>macOS 系统</strong> <a class="header-anchor" href="#🍎-macos-系统" aria-label="Permalink to &quot;🍎 **macOS 系统**&quot;">​</a></h4><ol><li>点击屏幕左上角的苹果图标，选择 <strong>“关于本机”</strong>。</li><li>在弹出的窗口中查看 <strong>“芯片”</strong> 一项：如果是 <strong>“Apple M1”</strong>、<strong>“M2”</strong>、<strong>“M3”</strong> 等系列，那么就是ARM64架构。如果是 <strong>Intel 处理器</strong>，则属于AMD64（x86_64）架构。</li></ol><h3 id="💡-根据架构如何选择和使用" tabindex="-1">💡 根据架构如何选择和使用 <a class="header-anchor" href="#💡-根据架构如何选择和使用" aria-label="Permalink to &quot;💡 根据架构如何选择和使用&quot;">​</a></h3><p>了解自己电脑的架构后，主要在两个场景下需要注意：</p><ul><li><strong>下载软件时</strong>：很多软件会为不同架构提供单独的安装包。务必选择和你的系统架构一致的版本（如Windows版选“ARM64”或“x64”， macOS版选“Apple芯片”或“Intel芯片”），否则软件可能无法安装或运行。</li><li><strong>安装操作系统时</strong>：为电脑重装或安装新的操作系统（如Linux发行版），必须选择与CPU架构匹配的系统镜像。</li></ul><p>总的来说，市面上绝大多数主流Windows笔记本和台式机都使用AMD64架构。如果你使用的是<strong>苹果在2020年后发布的Mac电脑</strong>、<strong>新款Windows on ARM笔记本</strong>（如部分高通芯片笔记本）或<strong>树莓派等开发板</strong>，那么你的电脑很可能就是ARM64架构。</p><h2 id="查看当前的电脑版本" tabindex="-1">查看当前的电脑版本 <a class="header-anchor" href="#查看当前的电脑版本" aria-label="Permalink to &quot;查看当前的电脑版本&quot;">​</a></h2><p>在win+r下执行，查看</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">winver</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><img src="'+o+'" alt=""></p>',23)])])}const u=e(r,[["render",l]]);export{m as __pageData,u as default};
